import { Column, Entity, JoinColumn, ManyToOne, Index, JoinTable, ManyToMany } from 'typeorm';
import { BaseEntity } from '../../../shared/entities/base-entity.entity';
import { User } from '../../user/entities/user.entity';
import { FocusMode } from './focus-mode.entity';
import { FocusModeTag } from './focus-mode-tags';
import { ToDo } from '../../to-do/entities/to-do.entity';

@Entity('completed_focus_blocks')
export class CompletedFocusBlock extends BaseEntity {
  constructor({ id, ...data }: Partial<CompletedFocusBlock> = {}, options = { generateId: false }) {
    super(id, options);
    Object.assign(this, { ...data, is_finished: !!data.finish_time });
  }

  @Index()
  @Column({
    type: 'uuid',
    nullable: false,
  })
  user_id?: string;

  @Index()
  @Column({
    type: 'uuid',
    nullable: false,
  })
  focus_mode_id?: string;

  @Column({
    type: 'timestamptz',
  })
  start_time?: Date;

  @Column({
    type: 'timestamptz',
  })
  finish_time?: Date;

  @Column({
    type: 'timestamptz',
  })
  scheduled_finish_time?: Date;

  @Column({
    type: 'varchar',
    length: 400,
    transformer: BaseEntity.encryptField('intention'),
  })
  intention?: string;

  @Column({
    type: 'varchar',
    length: 400,
    transformer: BaseEntity.encryptField('achievements'),
  })
  achievements?: string;

  @Column({
    type: 'varchar',
    length: 400,
    transformer: BaseEntity.encryptField('distractions'),
  })
  distractions?: string;

  @Column({
    type: 'numeric',
    default: 0,
    nullable: false,
  })
  focus_duration_seconds?: number;

  @Column({
    type: 'jsonb',
    transformer: BaseEntity.encryptJSONField('metadata'),
  })
  metadata?: any;

  @ManyToOne(() => User, (user) => user.completed_focus_blocks, { onDelete: 'CASCADE', onUpdate: 'CASCADE' })
  @JoinColumn({ name: 'user_id' })
  user?: User;

  @ManyToOne(() => FocusMode, (mode) => mode.completed_logs, { onDelete: 'CASCADE', onUpdate: 'CASCADE' })
  @JoinColumn({ name: 'focus_mode_id' })
  focus_mode?: FocusMode;

  @ManyToMany(() => FocusModeTag, { cascade: true, eager: true })
  @JoinTable()
  tags?: FocusModeTag[];

  @ManyToMany(() => ToDo, { cascade: true, eager: true })
  @JoinTable()
  to_dos?: ToDo[];
}
